return [{ json: {
  shop: 'REPLACE_STORE.myshopify.com', store: 'Your Store', form_url: 'https://REPLACE-N8N-DOMAIN/form/leave-a-review',
  ask_after_days: 3, ask_until_days: 10, remind_after_days: 3, max_per_day: 300,
  since: $now.minus({ days: 15 }).toISO()
} }];

const cfg = $('Set Review Config').first().json;
const log = $input.all().map(i => i.json).filter(r => r.request_id);
const byOrder = Object.fromEntries(log.map(r => [String(r.order_id), r]));
const now = Date.now(), day = 864e5;
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const out = [];
for (const e of $('Fetch Recently Fulfilled Orders').first().json.body?.data?.orders?.edges || []) {
  const o = e.node;
  const delivered = (o.fulfillments || []).map(f => f.deliveredAt).filter(Boolean).sort().pop();
  if (!delivered || /REFUNDED|VOIDED/.test(o.displayFinancialStatus) || (o.tags || []).includes('no-review')) continue;
  const age = (now - new Date(delivered).getTime()) / day;
  if (age < cfg.ask_after_days || age > cfg.ask_until_days || byOrder[o.legacyResourceId]) continue;
  const li = o.lineItems.edges[0]?.node || {};
  const phone = String(o.shippingAddress?.phone || o.phone || o.customer?.phone || '').replace(/\D/g, '').slice(-10);
  const rid = `RV-${o.legacyResourceId}`, token = hex(16);
  out.push({ json: { type: 'ask', request_id: rid, token, order_id: o.legacyResourceId, order_name: o.name, email: o.email || '',
    phone: phone ? '91' + phone : '', first_name: o.shippingAddress?.firstName || o.customer?.firstName || 'there',
    product_title: li.title || 'your order', product_id: li.product?.legacyResourceId || '', product_handle: li.product?.handle || '',
    delivered_at: delivered, link: `${cfg.form_url}?rid=${encodeURIComponent(rid)}&t=${token}` } });
}
for (const r of log.filter(r => r.status === 'asked' && !r.reminded_at && (now - new Date(r.asked_at).getTime()) / day >= cfg.remind_after_days))
  out.push({ json: { type: 'remind', ...r, link: `${cfg.form_url}?rid=${encodeURIComponent(r.request_id)}&t=${r.token}` } });
return out.slice(0, cfg.max_per_day);

const f = $('Customer Review Form').first();
const r = $input.first()?.json || {};
const ok = r.request_id && r.token && r.token === f.json.t && r.status !== 'reviewed';
const rating = Number(String(f.json['Rating'] || '').match(/(\d)\s*$/)?.[1] || 0);
return [{ json: { ...r, valid: !!ok, reason: ok ? '' : 'invalid or already used link', rating, title: f.json['Review title'] || '',
  body: f.json['Your review'] || '', display_name: f.json['Name to display'] || r.first_name || 'Customer',
  ad_consent: /^yes/i.test(f.json['May we feature your photos on our social media and ads?'] || '') }, binary: f.binary || {} }];

const r = $input.first().json, bins = $input.first().binary || {};
const keys = Object.keys(bins).slice(0, 4), imgs = [];
for (const k of keys) { const b = await this.helpers.getBinaryDataBuffer(0, k);
  imgs.push({ type: 'image_url', image_url: { url: `data:${bins[k].mimeType || 'image/jpeg'};base64,${b.toString('base64')}`, detail: 'low' } }); }
return [{ json: { ...r, photo_keys: keys, vision_body: { model: 'gpt-4o', temperature: 0, response_format: { type: 'json_object' }, messages: [
  { role: 'system', content: `You moderate customer reviews for an Indian e-commerce brand. You get the ordered product's name, the review text and 0-4 customer photos (in order, index 0..n-1).
Return ONLY JSON: {"photos": [{"index": number, "shows_product": boolean, "matches_ordered_product": boolean, "quality": number (1-10), "ad_score": number (1-10, how good it is as authentic UGC for social ads: lighting, framing, product clearly visible, lifestyle context),
"issues": [ "blurry"|"screenshot"|"stock_or_web_image"|"watermark"|"inappropriate"|"other_brand_prominent"|"personal_info_visible"|"irrelevant" ], "has_face": boolean, "caption_idea": string (max 12 words)}],
"text": {"sentiment": "positive"|"mixed"|"negative", "profanity": boolean, "personal_info": boolean, "spam_or_fake": boolean, "summary": string (max 20 words)}}` },
  { role: 'user', content: [{ type: 'text', text: `Ordered product: ${r.product_title}\nRating: ${r.rating}/5\nTitle: ${r.title}\nReview: ${r.body}\nPhotos: ${imgs.length}` }, ...imgs] } ] } },
  binary: bins }];

const p = $('Prepare Photo & Text Check').first();
let m = {};
try { m = JSON.parse($input.first().json.choices?.[0]?.message?.content || '{}'); } catch (e) { m = {}; }
const BAD = ['screenshot', 'stock_or_web_image', 'inappropriate', 'personal_info_visible', 'irrelevant'];
const photos = (m.photos || []).map(x => ({ ...x, key: p.json.photo_keys[x.index] })).filter(x => x.key);
const approved = photos.filter(x => x.shows_product && x.matches_ordered_product !== false && x.quality >= 5 && !(x.issues || []).some(i => BAD.includes(i)));
const ads = approved.filter(x => p.json.ad_consent && x.ad_score >= 7 && x.quality >= 7 && !(x.issues || []).includes('watermark'));
const t = m.text || {};
const textOk = !t.profanity && !t.personal_info && !t.spam_or_fake && String(p.json.body).trim().length >= 3;
return [{ json: { ...p.json, vision_body: undefined, moderation_ok: !!m.photos || !p.json.photo_keys.length, photos_total: p.json.photo_keys.length,
  approved_keys: approved.map(x => x.key), ad_photos: ads.map(x => ({ key: x.key, ad_score: x.ad_score, caption: x.caption_idea, has_face: x.has_face })),
  rejected_photos: photos.filter(x => !approved.includes(x)).map(x => `#${x.index + 1}: ${(x.issues || []).join(', ') || 'not the product'}`),
  text_ok: textOk, text_flags: ['profanity', 'personal_info', 'spam_or_fake'].filter(k => t[k]), sentiment: t.sentiment || '', summary: t.summary || '' },
  binary: p.binary }];

const r = $input.first();
return r.json.approved_keys.map((k, i) => ({ json: { request_id: r.json.request_id, file_name: `${r.json.request_id}_${i + 1}.${(r.binary[k].fileExtension || 'jpg')}` },
  binary: { data: r.binary[k] } }));

const r = $('Moderation Decision').first();
return r.json.ad_photos.map((p, i) => ({ json: { request_id: r.json.request_id, order_name: r.json.order_name, product_title: r.json.product_title,
  product_handle: r.json.product_handle, rating: r.json.rating, display_name: r.json.display_name, ad_score: p.ad_score, caption: p.caption, has_face: p.has_face,
  file_name: `UGC_${String(r.json.product_handle || 'product').slice(0, 30)}_${r.json.request_id}_${i + 1}.${r.binary[p.key].fileExtension || 'jpg'}` },
  binary: { data: r.binary[p.key] } }));

const r = $('Moderation Decision').first().json;
const cfg = $('Set Review Config').first().json;
const urls = $('Upload Review Photos').isExecuted ? $('Upload Review Photos').all().map(i => `https://drive.google.com/uc?export=view&id=${i.json.id}`) : [];
return [{ json: { ...r, picture_urls: urls, judgeme: { shop_domain: cfg.shop, platform: 'shopify', id: Number(r.product_id),
  email: r.email, name: r.display_name, rating: r.rating, title: r.title, body: r.body, picture_urls: urls, ip_addr: '' } } }];

